// Package catalog is tidebot's price catalog: a JSON file bundled into the
// binary at build time (generated by tools/pricecat from models.dev plus the
// vendor prices we verified by hand in internal/provider/prices.go), and an
// optional signed refresh of the same file published on the public releases
// repo. The order at run time is: the user's own prices > the preset's
// official prices from the active catalog > a per-model fallback from the
// catalog's generic model table (see Lookup).
//
// A refreshed catalog is only used when its ed25519 signature checks out
// against the updater's public key, it is newer than the bundled one and it
// hasn't lost a large share of the models (a broken upstream export must not
// wipe the prices; LiteLLM guards its remote map the same way).
package catalog

import (
	"crypto/ed25519"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/Zhengmingming1/tidebot/internal/pricing"
	"github.com/Zhengmingming1/tidebot/internal/updater"
)

// Schema is the catalog format version this build understands.
const Schema = 1

// signContext is prepended to the body before signing so a catalog signature
// can never be replayed as an update-manifest signature (same key).
const signContext = "tidebot-price-catalog/v1\n"

// File names in the data dir and on the releases page.
const (
	FileName = "prices.json"
	SigName  = "prices.json.sig"
)

//go:generate go run ../../../tools/pricecat gen -out prices.json

// MaxSize caps a downloaded catalog.
const MaxSize = 4 << 20

//go:embed prices.json
var bundledJSON []byte

// Source is one upstream the catalog was built from.
type Source struct {
	ID      string `json:"id"`
	Name    string `json:"name"`
	URL     string `json:"url"`
	Fetched string `json:"fetched"` // YYYY-MM-DD
}

// Catalog is the whole price file.
type Catalog struct {
	Schema    int                             `json:"schema"`
	Generated string                          `json:"generated"` // RFC 3339
	Sources   []Source                        `json:"sources"`
	Presets   map[string][]pricing.ModelPrice `json:"presets"` // preset id → verified official prices
	Models    map[string]pricing.ModelPrice   `json:"models"`  // model id → maker list price (USD)
	keys      []string
}

// Parse decodes and validates a catalog.
func Parse(b []byte) (*Catalog, error) {
	var c Catalog
	if err := json.Unmarshal(b, &c); err != nil {
		return nil, fmt.Errorf("price catalog: %w", err)
	}
	if c.Schema != Schema {
		return nil, fmt.Errorf("price catalog schema %d, this build reads %d", c.Schema, Schema)
	}
	if _, err := time.Parse(time.RFC3339, c.Generated); err != nil {
		return nil, errors.New("price catalog has no valid generated time")
	}
	for id, ps := range c.Presets {
		if err := pricing.Validate(pricing.Billing{}, ps); err != nil {
			return nil, fmt.Errorf("price catalog preset %s: %w", id, err)
		}
	}
	norm := make(map[string]pricing.ModelPrice, len(c.Models))
	for k, p := range c.Models {
		if err := pricing.Validate(pricing.Billing{}, []pricing.ModelPrice{p}); err != nil {
			return nil, fmt.Errorf("price catalog model %s: %w", k, err)
		}
		norm[pricing.Normalize(k)] = p
	}
	c.Models = norm
	for k := range c.Models {
		c.keys = append(c.keys, k)
	}
	return &c, nil
}

// Time is when the catalog was generated.
func (c *Catalog) Time() time.Time {
	t, _ := time.Parse(time.RFC3339, c.Generated)
	return t
}

// Count is the number of priced entries (presets + generic models).
func (c *Catalog) Count() (presets, models int) {
	for _, ps := range c.Presets {
		presets += len(ps)
	}
	return presets, len(c.Models)
}

var (
	dateSuffix = regexp.MustCompile(`(-\d{8}|-\d{4}-\d{2}-\d{2}|@\d{8}|-latest)$`)
)

// canonical strips what isn't part of a maker's model id: a router namespace
// ("anthropic/…", "moonshotai/…"), Claude Code's "[1m]" suffix, a version
// date and "-latest".
func canonical(model string) string {
	m := pricing.Normalize(model)
	if i := strings.LastIndexByte(m, '/'); i >= 0 {
		m = m[i+1:]
	}
	if i := strings.IndexByte(m, ':'); i > 0 {
		m = m[:i] // bedrock "…-v1:0", openrouter ":free"
	}
	return dateSuffix.ReplaceAllString(m, "")
}

// Lookup finds a generic price for model: exact id, then the id without
// namespace/date suffix, then the longest catalog id that is a prefix of it
// at a word boundary ("deepseek-v4-flash-0901" → "deepseek-v4-flash", but
// "gpt-4o" never matches "gpt-4"). Returns a copy, or nil.
func (c *Catalog) Lookup(model string) *pricing.ModelPrice {
	if c == nil || model == "" {
		return nil
	}
	for _, k := range []string{pricing.Normalize(model), canonical(model)} {
		if p, ok := c.Models[k]; ok {
			return &p
		}
	}
	m := canonical(model)
	best := ""
	for _, k := range c.keys {
		if len(k) > len(best) && len(m) > len(k) && strings.HasPrefix(m, k) && strings.ContainsRune("-._", rune(m[len(k)])) {
			best = k
		}
	}
	if best == "" {
		return nil
	}
	p := c.Models[best]
	return &p
}

// Preset returns the verified official prices for a preset id, or nil.
func (c *Catalog) Preset(id string) []pricing.ModelPrice {
	if c == nil {
		return nil
	}
	return c.Presets[id]
}

var (
	bundledOnce sync.Once
	bundled     *Catalog
	active      atomic.Pointer[Catalog]
)

// Bundled is the catalog compiled into this binary.
func Bundled() *Catalog {
	bundledOnce.Do(func() {
		c, err := Parse(bundledJSON)
		if err != nil {
			panic("bundled price catalog is invalid: " + err.Error())
		}
		bundled = c
	})
	return bundled
}

// Active is the catalog in use: a verified refresh if one was loaded, else the bundled one.
func Active() *Catalog {
	if c := active.Load(); c != nil {
		return c
	}
	return Bundled()
}

// Reset drops a loaded refresh (tests, "use bundled").
func Reset() { active.Store(nil) }

// Verify checks a catalog body against its base64 signature.
func Verify(pub string, body []byte, sig string) error {
	return updater.Verify(pub, append([]byte(signContext), body...), sig)
}

// Sign signs a catalog body (tools/pricecat; the key never leaves CI).
func Sign(priv []byte, body []byte) string {
	return updater.Sign(ed25519.PrivateKey(priv), append([]byte(signContext), body...))
}

// Errors from Accept.
var (
	ErrNotNewer = errors.New("price catalog is not newer than the one in use")
	ErrShrunk   = errors.New("price catalog lost too many models; keeping the current one")
)

// Accept decides whether next may replace cur.
func Accept(cur, next *Catalog) error {
	if !next.Time().After(cur.Time()) {
		return ErrNotNewer
	}
	cp, cm := cur.Count()
	np, nm := next.Count()
	if nm*2 < cm || np*2 < cp {
		return ErrShrunk
	}
	return nil
}

// Install verifies body/sig and, if acceptable, makes it active and saves it
// in dir. pub is the base64 ed25519 public key.
func Install(dir, pub string, body []byte, sig string) (*Catalog, error) {
	if err := Verify(pub, body, sig); err != nil {
		return nil, errors.New("price catalog signature is invalid")
	}
	c, err := Parse(body)
	if err != nil {
		return nil, err
	}
	if err := Accept(Active(), c); err != nil {
		return nil, err
	}
	if dir != "" {
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return nil, err
		}
		if err := writeAtomic(filepath.Join(dir, SigName), []byte(strings.TrimSpace(sig))); err != nil {
			return nil, err
		}
		if err := writeAtomic(filepath.Join(dir, FileName), body); err != nil {
			return nil, err
		}
	}
	active.Store(c)
	return c, nil
}

// Load re-verifies a saved refresh from dir and activates it when it is still
// newer than the bundled catalog (a later app version may ship a newer one).
func Load(dir, pub string) (*Catalog, error) {
	body, err := os.ReadFile(filepath.Join(dir, FileName))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	sig, err := os.ReadFile(filepath.Join(dir, SigName))
	if err != nil {
		return nil, err
	}
	if err := Verify(pub, body, string(sig)); err != nil {
		return nil, errors.New("saved price catalog signature is invalid")
	}
	c, err := Parse(body)
	if err != nil {
		return nil, err
	}
	if err := Accept(Bundled(), c); err != nil {
		return nil, nil // the bundled one is as new or newer
	}
	active.Store(c)
	return c, nil
}

func writeAtomic(path string, b []byte) error {
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, b, 0o600); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}
